/**
 * Fictional demo profile and simulated history (owner decision 2026-11-14).
 *
 * SIMULATED DEMO LOGIC: every value below is invented for the demonstration
 * and generated by code written with AI assistance. It is not real astronaut
 * data and is not derived from any dataset. See docs/data-and-limitations.md.
 */
import { addDays } from '@/domain/dates'
import type { HealthEntry } from '@/domain/indicators'

export const DEMO_PROFILE = {
  name: 'Demo astronaut',
  label: 'Fictional profile',
} as const

export const DEMO_DAYS = 14

/** Small deterministic generator, so the demo history is the same on every load. */
function mulberry32(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** One simulated entry per indicator per day for the 14 days before `now`, plus one PHQ-2 on the first day. */
export function createDemoEntries(now: Date): HealthEntry[] {
  const random = mulberry32(2026)
  const between = (min: number, max: number, decimals = 0) => {
    const factor = 10 ** decimals
    return Math.round((min + random() * (max - min)) * factor) / factor
  }
  const entries: HealthEntry[] = []

  for (let offset = DEMO_DAYS; offset >= 1; offset--) {
    const day = addDays(now, -offset)
    day.setHours(7, 0, 0, 0)
    const base = (name: string) => ({
      id: `demo-${name}-${offset}`,
      recordedAt: day.toISOString(),
      origin: 'simulated' as const,
    })
    entries.push(
      {
        ...base('bp'),
        indicator: 'bloodPressure',
        systolicMmHg: between(108, 118),
        diastolicMmHg: between(68, 76),
      },
      { ...base('hr'), indicator: 'heartRate', bpm: between(62, 70) },
      {
        ...base('glucose'),
        indicator: 'bloodGlucose',
        mgDl: between(82, 94),
        context: 'fasting',
        device: 'fingerstick',
      },
      {
        ...base('temp'),
        indicator: 'bodyTemperature',
        celsius: between(36.5, 36.9, 1),
        method: 'oral',
        exercisedLast30Min: false,
      },
      { ...base('sleep'), indicator: 'sleep', hours: between(6.5, 7.9, 1), source: 'selfReport' },
      { ...base('mood'), indicator: 'mood', kind: 'dailyRating', rating: between(3, 5) },
    )
    if (offset === DEMO_DAYS)
      entries.push({ ...base('phq2'), indicator: 'mood', kind: 'phq2', score: 0 })
  }
  return entries
}
